<?php
namespace Tests;
use App\Services\{Loyalty,SalonStore,Tenant};
use Illuminate\Support\Facades\{Artisan,DB,Http};
use Carbon\CarbonImmutable as Time;
class LoyaltyTest extends \Illuminate\Foundation\Testing\TestCase
{
 public function createApplication(){$app=require __DIR__.'/../bootstrap/app.php';$app->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();return $app;}
 protected function setUp():void{parent::setUp();Artisan::call('migrate',['--force'=>true]);Time::setTestNow('2036-05-05T08:00:00Z');$s=SalonStore::initial();$s['subscription']=['plan'=>'pro','status'=>'active'];$s['clients']=[['id'=>'c','name'=>'Guest','email'=>'guest@example.com','phone'=>'06301234567','guestId'=>10],['id'=>'other','name'=>'Other','email'=>'other@example.com','phone'=>'06309999999']];DB::table('salon_state')->insert(['id'=>1,'data'=>json_encode($s)]);DB::table('guest_accounts')->insert(['id'=>10,'provider'=>'email','subject'=>'ten','email'=>'guest@example.com','email_verified'=>true,'name'=>'Guest','created_at'=>now(),'updated_at'=>now()]);$this->withSession(['admin'=>true,'provider_id'=>1,'_token'=>'test-token'])->withHeader('X-CSRF-TOKEN','test-token');Http::preventStrayRequests();}
 protected function tearDown():void{Time::setTestNow();parent::tearDown();}
 private function configLoyalty(string $mode='visits',bool $enabled=true):void{$this->putJson('/api/loyalty',['enabled'=>$enabled,'rule'=>['mode'=>$mode,'pointsPerVisit'=>1,'spendUnit'=>1000],'rewards'=>[['id'=>'reward','name'=>'Kedvezmény','points'=>1,'amount'=>2000,'active'=>true,'services'=>[]]]])->assertOk();}
 private function earn(int $amount=8500):void{Time::setTestNow('2036-05-05T10:00:00Z');app(SalonStore::class)->mutate(function(&$s)use($amount){$s['bookings'][]=['id'=>'earned','clientId'=>'c','name'=>'Guest','email'=>'guest@example.com','phone'=>'06301234567','staff'=>'anna','services'=>['cut'],'start'=>'2036-05-05T09:00:00.000000Z','createdAt'=>'2036-05-05T08:00:00.000000Z','updatedAt'=>'v1','status'=>'confirmed','attendance'=>'attended','serviceSnapshot'=>[['id'=>'cut','price'=>$amount,'duration'=>45,'name'=>'Cut']]];$s['payments'][]=['id'=>'paid','bookingId'=>'earned','amount'=>$amount,'status'=>'paid','refundedAmount'=>0,'method'=>'cash','paidAt'=>now()->toISOString()];});}
 private function state():array{return app(SalonStore::class)->read();}
 public function test_default_disabled_and_award_requires_attendance_payment_and_past_date_without_duplicates():void{
  $this->assertFalse($this->state()['settings']['loyaltyEnabled']);$this->configLoyalty();$this->earn();$this->assertSame(1,Loyalty::balance($this->state(),'c'));for($i=0;$i<3;$i++)app(SalonStore::class)->mutate(fn(&$s)=>null);$this->assertCount(1,$this->state()['loyalty']['ledger']);app(SalonStore::class)->mutate(function(&$s){$s['payments'][0]['status']='void';});$this->assertSame(0,Loyalty::balance($this->state(),'c'));app(SalonStore::class)->mutate(function(&$s){$s['payments'][0]['status']='paid';$s['bookings'][0]['attendance']='no_show';});$this->assertSame(0,Loyalty::balance($this->state(),'c'));
 }
 public function test_no_retroactive_awards_and_disabled_period_does_not_backfill():void{
  $this->earn();$this->configLoyalty();$this->assertSame(0,Loyalty::balance($this->state(),'c'));$this->configLoyalty('visits',false);Time::setTestNow('2036-05-06T10:00:00Z');app(SalonStore::class)->mutate(function(&$s){$s['bookings'][0]['start']='2036-05-06T09:00:00.000000Z';});$this->configLoyalty();$this->assertSame(0,Loyalty::balance($this->state(),'c'));
 }
 public function test_spend_rule_is_snapshotted_and_refund_or_deletion_reconciles_even_when_disabled():void{
  $this->configLoyalty('spend');$this->earn();$this->assertSame(8,Loyalty::balance($this->state(),'c'));$this->configLoyalty('visits');$this->assertSame(8,Loyalty::balance($this->state(),'c'));$this->configLoyalty('visits',false);app(SalonStore::class)->mutate(function(&$s){$s['payments'][0]['refundedAmount']=2500;});$this->assertSame(6,Loyalty::balance($this->state(),'c'));app(SalonStore::class)->mutate(function(&$s){$s['bookings']=[];});$this->assertSame(0,Loyalty::balance($this->state(),'c'));
 }
 public function test_booking_quote_and_actual_reservation_use_points_and_cancellation_returns_them():void{
  $this->configLoyalty();$this->earn();$quote=$this->postJson('/api/quote',['services'=>['cut'],'clientId'=>'c','loyaltyRewardId'=>'reward'])->assertOk();$this->assertSame(2000,$quote->json('discount'));$this->assertSame(1,Loyalty::balance($this->state(),'c'));
  $b=$this->postJson('/api/bookings',['services'=>['cut'],'clientId'=>'c','staff'=>'anna','start'=>'2036-05-06T08:00:00Z','loyaltyRewardId'=>'reward'])->assertCreated()->json();$this->assertSame(2000,$b['pricing']['discount']);$this->assertSame(0,Loyalty::balance($this->state(),'c'));$this->postJson('/api/quote',['services'=>['cut'],'clientId'=>'c','loyaltyRewardId'=>'reward'])->assertUnprocessable();
  $this->configLoyalty('visits',false);app(SalonStore::class)->mutate(function(&$s)use($b){foreach($s['bookings'] as &$booking)if($booking['id']===$b['id'])$booking['status']='cancelled';});$this->assertSame(1,Loyalty::balance($this->state(),'c'));
 }
 public function test_guest_cannot_spend_other_clients_points_or_use_disabled_feature():void{
  $this->configLoyalty();$this->earn();$this->withSession(['admin'=>false,'guest_id'=>10]);$this->getJson('/api/guest/loyalty')->assertOk()->assertJsonPath('balance',1);$this->postJson('/api/quote',['services'=>['cut'],'clientId'=>'other','loyaltyRewardId'=>'reward','public'=>true])->assertOk();$this->withSession(['guest_id'=>999]);$this->postJson('/api/quote',['services'=>['cut'],'clientId'=>'c','loyaltyRewardId'=>'reward','public'=>true])->assertNotFound();$this->getJson('/api/loyalty')->assertForbidden();$this->getJson('/api/clients/c/loyalty')->assertForbidden();
 }
 public function test_coupon_pass_and_service_restrictions_cannot_be_bypassed():void{
  $this->configLoyalty();$this->earn();$s=$this->state();$b=['id'=>'x','clientId'=>'c','services'=>['cut'],'serviceSnapshot'=>[['price'=>8500]],'pricing'=>['original'=>8500,'couponId'=>'x']];try{Loyalty::reserve($s,$b,'reward',true);$this->fail('Expected rejection');}catch(\InvalidArgumentException $e){$this->assertStringContainsString('kuponnal',$e->getMessage());}$b['pricing']=['original'=>8500];$s['loyalty']['rewards'][0]['services']=['other-service'];$this->expectException(\InvalidArgumentException::class);Loyalty::reserve($s,$b,'reward',true);
 }
 public function test_balance_can_be_negative_after_spent_award_is_refunded_and_other_tenant_is_isolated():void{
  $this->configLoyalty();$this->earn();app(SalonStore::class)->mutate(function(&$s){$b=['id'=>'reserved','clientId'=>'c','staff'=>'anna','services'=>['cut'],'start'=>'2036-05-06T08:00:00Z','updatedAt'=>'v1','status'=>'confirmed','serviceSnapshot'=>[['price'=>8500]],'pricing'=>['original'=>8500]];Loyalty::reserve($s,$b,'reward',true);$s['bookings'][]=$b;$s['payments'][0]['refundedAmount']=8500;});$this->assertSame(-1,Loyalty::balance($this->state(),'c'));DB::table('salon_state')->insert(['id'=>2,'data'=>json_encode(SalonStore::initial())]);app(Tenant::class)->run(2,function(){$this->assertSame(0,Loyalty::balance(app(SalonStore::class)->read(),'c'));});
 }
 public function test_future_attended_booking_waits_until_its_time_and_guest_must_be_verified_to_redeem():void{
  $this->configLoyalty();$this->earn();app(SalonStore::class)->mutate(function(&$s){$s['bookings'][0]['start']='2036-05-06T09:00:00.000000Z';});$this->assertSame(0,Loyalty::balance($this->state(),'c'));Time::setTestNow('2036-05-06T10:00:00Z');app(SalonStore::class)->mutate(fn(&$s)=>null);$this->assertSame(1,Loyalty::balance($this->state(),'c'));DB::table('guest_accounts')->where('id',10)->update(['email_verified'=>false]);$this->withSession(['admin'=>false,'guest_id'=>10]);$this->postJson('/api/quote',['services'=>['cut'],'public'=>true,'loyaltyRewardId'=>'reward'])->assertForbidden();
 }
 public function test_restoring_a_cancelled_reward_booking_requires_available_points_and_rolls_back():void{
  $this->configLoyalty();$this->earn();app(SalonStore::class)->mutate(function(&$s){$b=['id'=>'r1','clientId'=>'c','staff'=>'anna','services'=>['cut'],'start'=>'2036-05-06T08:00:00Z','updatedAt'=>'v1','status'=>'confirmed','serviceSnapshot'=>[['price'=>8500]],'pricing'=>['original'=>8500]];Loyalty::reserve($s,$b,'reward',true);$s['bookings'][]=$b;});app(SalonStore::class)->mutate(function(&$s){$s['bookings'][1]['status']='cancelled';});$this->assertSame(1,Loyalty::balance($this->state(),'c'));app(SalonStore::class)->mutate(function(&$s){$b=$s['bookings'][1];$b['id']='r2';$b['status']='confirmed';$b['pricing']=['original'=>8500];Loyalty::reserve($s,$b,'reward',true);$s['bookings'][]=$b;});try{app(SalonStore::class)->mutate(function(&$s){$s['bookings'][1]['status']='confirmed';});$this->fail('Expected insufficient points');}catch(\InvalidArgumentException $e){$this->assertStringContainsString('nincs elegendő pont',$e->getMessage());}$this->assertSame('cancelled',$this->state()['bookings'][1]['status']);$this->assertSame(0,Loyalty::balance($this->state(),'c'));
 }
 public function test_disabled_feature_rejects_redemption_and_keeps_balance_and_history():void{
  $this->configLoyalty();$this->earn();$this->configLoyalty('visits',false);$this->postJson('/api/quote',['services'=>['cut'],'clientId'=>'c','loyaltyRewardId'=>'reward'])->assertUnprocessable();$this->assertSame(1,Loyalty::balance($this->state(),'c'));$this->withSession(['admin'=>false,'guest_id'=>10]);$this->getJson('/api/guest/loyalty')->assertExactJson(['enabled'=>false]);
 }

 public function test_verified_guest_booking_reserves_own_points_and_cannot_earn_on_the_reward():void{
  $this->configLoyalty();$this->earn();$this->withSession(['admin'=>false,'guest_id'=>10]);$b=$this->postJson('/api/bookings',['public'=>true,'services'=>['cut'],'staff'=>'anna','start'=>'2036-05-06T08:00:00Z','name'=>'Guest','email'=>'guest@example.com','phone'=>'06301234567','loyaltyRewardId'=>'reward'])->assertCreated()->json();$this->assertSame(2000,$b['pricing']['discount']);$this->assertSame(0,Loyalty::balance($this->state(),'c'));Time::setTestNow('2036-05-07T10:00:00Z');app(SalonStore::class)->mutate(function(&$s)use($b){foreach($s['bookings'] as &$booking)if($booking['id']===$b['id'])$booking['attendance']='attended';$s['payments'][]=['id'=>'reward-paid','bookingId'=>$b['id'],'amount'=>$b['pricing']['payable'],'status'=>'paid'];});$this->assertSame(0,Loyalty::balance($this->state(),'c'));
 }

}
